     9	
    10	const HeroScene = dynamic(
    11	  () => import("@/components/hero/hero-scene").then((m) => m.HeroScene),
    12	  { ssr: false, loading: () => null },
    13	);
    14	
    15	/**
    16	 * Decides whether this device gets the WebGL hero at all.
    17	 *
    18	 * The scene is decoration layered behind real, server-rendered text — it never
    19	 * carries content and it must never delay the LCP. So it mounts only once the
    20	 * capability gate in `lib/webgl.ts` passes and the browser has gone idle.
    21	 * Everyone else keeps the gradient hero, which is what the page renders
    22	 * anyway (CLAUDE.md §7).
    23	 */
    24	export function HeroCanvas() {
    25	  const reducedMotion = useReducedMotionPreference();
    26	  const [allowed, setAllowed] = useState(false);
    27	
    28	  useEffect(() => {
    29	    if (!shouldRenderWebGL(reducedMotion)) return;
    30	
    31	    // Wait for the main thread to go quiet so the scene never competes with
    32	    // hydration or the LCP paint.
    33	    const schedule =
    34	      window.requestIdleCallback ?? ((cb: IdleRequestCallback) => setTimeout(cb, 1200));
    35	    const handle = schedule(() => setAllowed(true));
    36	
    37	    return () => {
    38	      if (window.cancelIdleCallback && typeof handle === "number") {
    39	        window.cancelIdleCallback(handle);
    40	      }
    41	    };
    42	  }, [reducedMotion]);
    43	
    44	  if (!allowed) return null;
    45	
    46	  return (
    47	    <WebGLBoundary>
    48	      <div
    49	        className="pointer-events-none absolute inset-0 opacity-0 [animation:fade-in-canvas_1.2s_ease-out_forwards]"
    50	        aria-hidden
    51	      >
    52	        <HeroScene />
    53	      </div>
    54	    </WebGLBoundary>
    55	  );
    56	}
