     1	"use client";
     2	
     3	import { useMemo, useRef } from "react";
     4	import { Canvas, useFrame, type ThreeElements } from "@react-three/fiber";
     5	import { Environment } from "@react-three/drei";
     6	import * as THREE from "three";
     7	
     8	/**
     9	 * The hero scene.
    10	 *
    11	 * Atmosphere, not spectacle. A slow parallax over an abstract massing of
    12	 * towers, lit like an architectural model — the point is that the page feels
    13	 * expensive, not that anyone examines the geometry (CLAUDE.md §7).
    14	 *
    15	 * Budget discipline: well under 100k triangles and 30 draw calls, DPR capped
    16	 * at 1.5, no allocation inside the frame loop, and the whole canvas is mounted
    17	 * only by a wrapper that has already decided the device can afford it.
    18	 */
    19	
    20	/** Deterministic massing, so server and client agree and builds are stable. */
    21	const BLOCKS = [
    22	  { x: -3.2, z: -1.4, w: 0.9, h: 3.4, d: 0.9 },
    23	  { x: -2.0, z: 0.6, w: 1.1, h: 2.2, d: 1.0 },
    24	  { x: -0.6, z: -0.8, w: 1.0, h: 4.6, d: 1.0 },
    25	  { x: 0.8, z: 0.9, w: 1.2, h: 2.9, d: 1.1 },
    26	  { x: 2.2, z: -1.1, w: 0.9, h: 3.9, d: 0.9 },
    27	  { x: 3.5, z: 0.4, w: 1.0, h: 2.4, d: 1.0 },
    28	];
    29	
    30	export function HeroScene() {
    31	  return (
    32	    <Canvas
    33	      // Capping DPR is the single most effective mobile GPU saving available.
    34	      dpr={[1, 1.5]}
    35	      gl={{ antialias: true, powerPreference: "high-performance" }}
    36	      camera={{ position: [0, 3.4, 9], fov: 38 }}
    37	      // Nothing animates on its own except our drift, so frameloop stays on
    38	      // demand-free but the renderer still parks when the tab is hidden.
    39	      onCreated={({ gl }) => {
    40	        gl.toneMapping = THREE.ACESFilmicToneMapping;
    41	        gl.toneMappingExposure = 1.05;
    42	      }}
    43	    >
    44	      <color attach="background" args={["#141414"]} />
    45	      <fog attach="fog" args={["#141414", 9, 20]} />
    46	
    47	      {/* Architectural studio lighting: soft ambient, one keyed directional. */}
    48	      <ambientLight intensity={0.45} />
    49	      <directionalLight
    50	        position={[4, 8, 5]}
    51	        intensity={1.6}
    52	        color="#f5f1e8"
    53	        castShadow={false}
    54	      />
    55	      <directionalLight position={[-6, 3, -4]} intensity={0.4} color="#b99c6b" />
    56	
    57	      <Environment preset="dawn" />
    58	
    59	      <Massing />
    60	      <Ground />
    61	    </Canvas>
    62	  );
    63	}
    64	
    65	function Massing() {
    66	  const group = useRef<THREE.Group>(null);
    67	
    68	  // Materials are created once and shared across every block, which keeps the
    69	  // draw-call count down and avoids per-frame allocation.
    70	  const material = useMemo(
    71	    () =>
    72	      new THREE.MeshStandardMaterial({
    73	        color: "#2a2622",
    74	        roughness: 0.35,
    75	        metalness: 0.6,
    76	      }),
    77	    [],
    78	  );
    79	
    80	  const accent = useMemo(
    81	    () =>
    82	      new THREE.MeshStandardMaterial({
    83	        color: "#b99c6b",
    84	        roughness: 0.25,
    85	        metalness: 0.85,
    86	      }),
    87	    [],
    88	  );
    89	
    90	  useFrame((state) => {
    91	    if (!group.current) return;
    92	    // A very slow drift keyed to the pointer. No new objects per frame.
    93	    const t = state.clock.elapsedTime;
    94	    group.current.rotation.y = Math.sin(t * 0.08) * 0.12 + state.pointer.x * 0.08;
    95	    group.current.position.y = Math.sin(t * 0.25) * 0.04;
    96	  });
    97	
    98	  return (
    99	    <group ref={group}>
   100	      {BLOCKS.map((block, index) => (
   101	        <mesh
   102	          key={index}
   103	          position={[block.x, block.h / 2, block.z]}
   104	          material={index === 2 ? accent : material}
   105	        >
   106	          <boxGeometry args={[block.w, block.h, block.d]} />
   107	        </mesh>
   108	      ))}
   109	    </group>
   110	  );
   111	}
   112	
   113	function Ground(props: ThreeElements["mesh"]) {
   114	  return (
   115	    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} {...props}>
   116	      <planeGeometry args={[60, 60]} />
   117	      <meshStandardMaterial color="#1a1a1a" roughness={0.9} metalness={0.1} />
   118	    </mesh>
   119	  );
   120	}
