     9	/**
    10	 * The home hero.
    11	 *
    12	 * A scroll-scrubbed sequence over the building, with the headline pinned in
    13	 * front of it. The copy and both calls to action are ordinary markup — the
    14	 * sequence sits behind them and can fail completely without taking the hero
    15	 * with it.
    16	 */
    17	const framePath = (index: number) =>
    18	  `/frames/hero/${String(index).padStart(3, "0")}.webp`;
    19	
    20	export function HomeHero() {
    21	  return (
    22	    <ScrollFrameSequence
    23	      frameCount={36}
    24	      framePath={framePath}
    25	      poster="/frames/hero/001.webp"
    26	      className="relative h-[250svh]"
    27	    >
    28	      {/* Scrim: the render is bright, the type is light. */}
    29	      <div
    30	        aria-hidden
    31	        className="absolute inset-0 bg-gradient-to-b from-charcoal/75 via-charcoal/40 to-charcoal/85"
    32	      />
    33	
    34	      <div className="relative flex h-full items-end">
    35	        <div className="container-page pb-[12vh]">
    36	          <p className="eyebrow text-gold-soft animate-[rise_0.9s_var(--ease-entrance)_both]">
    37	            Ahmedabad · Since {siteConfig.foundedYear}
    38	          </p>
    39	
    40	          <h1 className="text-ivory mt-6 max-w-[16ch] text-h2 leading-[1.02] md:text-h1">
    41	            <span className="block animate-[rise_1s_var(--ease-entrance)_0.08s_both]">
    42	              A trusted builder
    43	            </span>
    44	            <span className="block animate-[rise_1s_var(--ease-entrance)_0.16s_both]">
    45	              in Ahmedabad.
    46	            </span>
    47	          </h1>
    48	
    49	          <p className="measure text-lead text-ivory/70 mt-8 animate-[rise_1s_var(--ease-entrance)_0.28s_both]">
    50	            {siteConfig.stats.yearsExperience} years, {siteConfig.stats.completedProjects}{" "}
    51	            completed projects and {siteConfig.stats.happyFamilies.toLocaleString("en-IN")}{" "}
    52	            families who live in something we built.
    53	          </p>
    54	
    55	          <div className="mt-10 flex flex-wrap gap-4 animate-[rise_1s_var(--ease-entrance)_0.36s_both]">
    56	            <Link
    57	              href="/projects"
    58	              className="eyebrow bg-gold text-charcoal rounded-sm px-8 py-4 transition-transform duration-300 hover:-translate-y-0.5"
    59	            >
    60	              View Projects
    61	            </Link>
    62	            <a
    63	              href={whatsappLink()}
    64	              target="_blank"
    65	              rel="noopener noreferrer"
    66	              className="eyebrow text-ivory hover:bg-ivory hover:text-charcoal rounded-sm border border-ivory/30 px-8 py-4 transition-colors duration-300"
    67	            >
    68	              WhatsApp Us
    69	            </a>
    70	          </div>
    71	        </div>
    72	      </div>
    73	
    74	      {/* Scroll affordance — the hero is 250vh, so it has to invite the move. */}
    75	      <div
    76	        aria-hidden
    77	        className="text-ivory/50 absolute bottom-8 left-1/2 -translate-x-1/2"
    78	      >
    79	        <span className="eyebrow block animate-[nudge_2.4s_ease-in-out_infinite]">
    80	          Scroll
    81	        </span>
    82	      </div>
    83	    </ScrollFrameSequence>
    84	  );
    85	}
