     1	/**
     2	 * Decides whether a device should be given a WebGL scene at all.
     3	 *
     4	 * Every 3D surface on this site is decoration layered over content that
     5	 * already works, so the bar for mounting one is deliberately high: a real GL
     6	 * context, a pointer device, a wide viewport, enough cores, and no
     7	 * reduced-motion preference (CLAUDE.md §7).
     8	 */
     9	
    10	/**
    11	 * Actually creates a context rather than sniffing for support. Browsers report
    12	 * WebGL as available in situations where context creation still fails —
    13	 * blocklisted drivers, exhausted context limits, headless environments — and a
    14	 * canvas that mounts without a context is worse than no canvas at all.
    15	 */
    16	export function hasWebGL(): boolean {
    17	  if (typeof window === "undefined") return false;
    18	
    19	  try {
    20	    const canvas = document.createElement("canvas");
    21	    const gl =
    22	      canvas.getContext("webgl2") ??
    23	      canvas.getContext("webgl") ??
    24	      canvas.getContext("experimental-webgl");
    25	
    26	    if (!gl) return false;
    27	
    28	    // Release the probe context immediately; browsers cap how many can exist.
    29	    const lose = (gl as WebGLRenderingContext).getExtension("WEBGL_lose_context");
    30	    lose?.loseContext();
    31	
    32	    return true;
    33	  } catch {
    34	    return false;
    35	  }
    36	}
    37	
    38	/** True when the device looks too small or too weak to be worth the GPU cost. */
    39	export function isLowCapabilityDevice(): boolean {
    40	  if (typeof window === "undefined") return true;
    41	
    42	  const coarse = window.matchMedia("(pointer: coarse)").matches;
    43	  const narrow = window.matchMedia("(max-width: 1023px)").matches;
    44	
    45	  // deviceMemory is Chromium-only; its absence is not evidence of weakness.
    46	  const memory = (navigator as { deviceMemory?: number }).deviceMemory;
    47	  const lowMemory = memory !== undefined && memory < 4;
    48	  const fewCores = navigator.hardwareConcurrency < 4;
    49	
    50	  return coarse || narrow || lowMemory || fewCores;
    51	}
    52	
    53	/** The full gate. `reducedMotion` comes from the app-wide provider. */
    54	export function shouldRenderWebGL(reducedMotion: boolean): boolean {
    55	  return !reducedMotion && !isLowCapabilityDevice() && hasWebGL();
    56	}
