     1	"use client";
     2	
     3	import { m, type HTMLMotionProps } from "framer-motion";
     4	
     5	import { useReducedMotionPreference } from "@/components/providers/reduced-motion-provider";
     6	
     7	type FadeInViewProps = Omit<HTMLMotionProps<"div">, "children"> & {
     8	  children?: React.ReactNode;
     9	  /** Seconds of stagger before this element animates. Keep small. */
    10	  delay?: number;
    11	  /** Vertical travel in px. 16–24 reads as composure; more reads as a demo. */
    12	  distance?: number;
    13	};
    14	
    15	/**
    16	 * The default reveal for section content.
    17	 *
    18	 * Built on Framer Motion's `m` primitive rather than `motion`: `m` carries no
    19	 * features of its own and draws them from the single `LazyMotion` boundary in
    20	 * the root layout, which is what keeps a page of a dozen reveals affordable.
    21	 *
    22	 * Animates opacity and transform only, so it composites on the GPU and holds
    23	 * 60fps; fires once per element; resolves in 500ms, the ceiling set in
    24	 * CLAUDE.md §6.
    25	 *
    26	 * When the visitor prefers reduced motion the element renders in its final
    27	 * state: same markup, same layout, no movement.
    28	 */
    29	export function FadeInView({
    30	  children,
    31	  delay = 0,
    32	  distance = 20,
    33	  ...props
    34	}: FadeInViewProps) {
    35	  const reducedMotion = useReducedMotionPreference();
    36	  const hidden = reducedMotion
    37	    ? { opacity: 1, y: 0 }
    38	    : { opacity: 0, y: distance };
    39	
    40	  return (
    41	    <m.div
    42	      initial={hidden}
    43	      whileInView={{ opacity: 1, y: 0 }}
    44	      viewport={{ once: true, margin: "-100px" }}
    45	      transition={
    46	        reducedMotion
    47	          ? { duration: 0 }
    48	          : { duration: 0.5, delay, ease: [0.22, 1, 0.36, 1] }
    49	      }
    50	      {...props}
    51	    >
    52	      {children}
    53	    </m.div>
    54	  );
    55	}
