     6	
     7	/**
     8	 * GSAP-driven scroll choreography for headline sections.
     9	 *
    10	 * Framer Motion covers component-level reveals; this handles the scroll-linked
    11	 * work it is not built for — a word-by-word headline reveal tied to scroll
    12	 * position, plus a parallax drift on the block behind it.
    13	 *
    14	 * GSAP and ScrollTrigger load on demand rather than in the page bundle, and
    15	 * only after the reduced-motion and viewport checks pass, so visitors who will
    16	 * never see the effect never download it either.
    17	 */
    18	export function ScrollReveal({
    19	  children,
    20	  parallax = false,
    21	}: {
    22	  children: React.ReactNode;
    23	  /** Adds a slow vertical drift as the section passes through the viewport. */
    24	  parallax?: boolean;
    25	}) {
    26	  const container = useRef<HTMLDivElement>(null);
    27	  const reducedMotion = useReducedMotionPreference();
